def fun():
	t = int(input())
	for a0 in range(t):
		(n, q) = map(int, input().strip().split())
		arr = []
		ans = []
		flag = 0
		for i in range(n + 1):
			arr.append([])
			ans.append(-1)
		for i in range(q):
			(a, b) = map(int, input().strip().split())
			arr[a].append(b)
			if a >= b:
				flag = 1
		if flag == 1:
			print(-1)
			continue
		s = len(arr[0])
		po = [i for i in range(1, s + 1)]
		pok = tuple(po)
		pos = [list(pok) for i in range(n)]
		ans[0] = 0
		for i in range(n):
			arr[i].sort()
			j = 0
			if ans[i] == -1:
				flag = 1
				break
			while j < len(arr[i]):
				if ans[arr[i][j]] == -1:
					if len(pos[i]) == 0:
						flag = 1
						break
					else:
						ans[arr[i][j]] = pos[i][0]
						arr_remove = arr[i][j]
						pos_remove = pos[i][0]
						remove_till = arr[i][j]
						pos[i].pop(0)
						m = i + 1
						while m < remove_till:
							if arr_remove not in arr[m] or pos_remove not in pos[m]:
								flag = 1
								break
							arr[m].remove(arr_remove)
							pos[m].remove(pos_remove)
							m = m + 1
				j = j + 1
			if len(pos[i]) != 0:
				ks = 0
				ke = len(pos[i])
				while ks != ke:
					ls = i + 1
					mc = pos[i][ks]
					while ls != n:
						pos[ls].remove(mc)
						ls = ls + 1
					ks = ks + 1
		if ans[n] == -1:
			flag = 1
		if flag == 1:
			print(-1)
		else:
			for i in range(1, n + 1):
				print(ans[i], end=' ')
			print()
fun()
